weekday_map = {
    'Monday': MO,
    'Tuesday': TU,
    'Wednesday': WE,
    'Thursday': TH,
    'Friday': FR,
    'Saturday': SA,
    'Sunday': SU,
}

def _to_int(value, name):
    if value is None:
        return 0
    try:
        return int(value)
    except (TypeError, ValueError):
        raise ValueError(f'{name} must be an integer')

try:
    base = parse(base_date).date()
except Exception as exc:
    raise ValueError(f'Invalid base_date: {exc}')

years_i = _to_int(years, 'years')
months_i = _to_int(months, 'months')
days_i = _to_int(days, 'days')
weeks_i = _to_int(weeks, 'weeks')

if weekday is None or (isinstance(weekday, str) and weekday.strip() == ''):
    weekday_name = ''
    weekday_value = None
    occurrence_applied = 0
else:
    if not isinstance(weekday, str):
        raise ValueError('weekday must be a string')
    weekday_key = weekday.strip().capitalize()
    if weekday_key not in weekday_map:
        raise ValueError(f'Unsupported weekday: {weekday}')
    occurrence = 1 if weekday_occurrence is None else weekday_occurrence
    try:
        occurrence = int(occurrence)
    except (TypeError, ValueError):
        raise ValueError('weekday_occurrence must be an integer')
    if occurrence == 0:
        occurrence = 1
    weekday_value = weekday_map[weekday_key](occurrence)
    weekday_name = weekday_key
    occurrence_applied = occurrence

rd = relativedelta(years=years_i, months=months_i, days=days_i, weeks=weeks_i, weekday=weekday_value)
result = base + rd

return {
    'original_date': base.isoformat(),
    'result_date': result.isoformat(),
    'result_weekday': result.strftime('%A'),
    'years_applied': years_i,
    'months_applied': months_i,
    'days_applied': rd.days,
    'weeks_applied': weeks_i,
    'weekday_applied': weekday_name,
    'weekday_occurrence_applied': occurrence_applied,
}

try:
    start = parse(start_date).date()
except Exception as exc:
    raise ValueError(f'Invalid start_date: {exc}')

try:
    end = parse(end_date).date()
except Exception as exc:
    raise ValueError(f'Invalid end_date: {exc}')

rd = relativedelta(end, start)

return {
    'start_date': start.isoformat(),
    'end_date': end.isoformat(),
    'years': rd.years,
    'months': rd.months,
    'days': rd.days,
    'total_days': (end - start).days,
    'start_weekday': start.strftime('%A'),
    'end_weekday': end.strftime('%A'),
}

try:
    year_i = int(year)
except (TypeError, ValueError):
    raise ValueError('year must be an integer')

method_map = {
    'western': EASTER_WESTERN,
    'orthodox': EASTER_ORTHODOX,
    'julian': EASTER_JULIAN,
}
method_key = 'western' if method is None else str(method).strip().lower()
if method_key not in method_map:
    raise ValueError(f'Unsupported Easter method: {method}')

result = easter(year_i, method=method_map[method_key])

return {
    'year': year_i,
    'method': method_key,
    'date': result.isoformat(),
    'weekday': result.strftime('%A'),
}

if not isinstance(text, str):
    raise ValueError('text must be a string')

try:
    dt = parse(text)
except Exception as exc:
    raise ValueError(f'Invalid date string: {exc}')

return {
    'input': text,
    'iso_date': dt.date().isoformat(),
    'iso_datetime': dt.isoformat(),
    'year': dt.year,
    'month': dt.month,
    'day': dt.day,
    'weekday': dt.strftime('%A'),
    'day_of_year': dt.timetuple().tm_yday,
}
